inlineStyleBlocks.css:
/* Journal Paper Ruling & Red Margin Line */
.journal-ruled-canvas {
  background-color: #fdf9f1;
  background-image: 
    linear-gradient(to right, transparent 38px, rgba(223, 164, 149, 0.45) 38px, rgba(223, 164, 149, 0.45) 39.5px, transparent 39.5px),
    linear-gradient(to bottom, transparent 25px, rgba(216, 207, 190, 0.35) 25px, rgba(216, 207, 190, 0.35) 26px);
  background-size: 100% 26px, 100% 26px;
  background-attachment: local;
}
.custom-scroll::-webkit-scrollbar {
  width: 4px;
}
.custom-scroll::-webkit-scrollbar-track {
  background: #f1ede6;
}
.custom-scroll::-webkit-scrollbar-thumb {
  background: #c5c6ce;
  border-radius: 2px;
}
.custom-scroll::-webkit-scrollbar-thumb:hover {
  background: #75777e;
}
.double-rule {
  border-bottom: 1px solid #c5c6ce;
  box-shadow: 0 2px 0 0 #fdf9f1, 0 3px 0 0 #c5c6ce;
}
.stamp-wax {
  box-shadow: inset 0 1px 2px rgba(255,255,255,0.4), inset 0 -1px 2px rgba(0,0,0,0.25), 0 1px 3px rgba(158, 61, 36, 0.2);
}
.brass-accent {
  background: linear-gradient(135deg, #d4af37 0%, #aa8222 100%);
  box-shadow: 0 1px 2px rgba(0,0,0,0.2);
}
.strikethrough-ink {
  position: relative;
}
.strikethrough-ink::after {
  content: '';
  position: absolute;
  left: -2px;
  right: -2px;
  top: 52%;
  height: 1.5px;
  background: #1a2744;
  opacity: 0.75;
  transform: rotate(-0.7deg);
}

body {
  font-feature-settings: "kern" 1, "liga" 1, "calt" 1;
}
.material-symbols-outlined {
  font-size: 18px;
  line-height: 1;
  display: inline-block;
  vertical-align: middle;
}
/* Subtle ruled ledger guide line */
.ledger-ruled-card {
  background-image: linear-gradient(to bottom, transparent 25px, rgba(216, 207, 190, 0.4) 26px);
  background-size: 100% 26px;
}

.material-symbols-outlined {
  font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 20;
  line-height: 1;
  display: inline-block;
  vertical-align: middle;
}
.seyes-line {
  background-image: linear-gradient(to bottom, transparent 25px, #e5decfa8 26px);
  background-size: 100% 26px;
}

.material-symbols-outlined {
  font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 20;
  display: inline-block;
  vertical-align: middle;
  line-height: 1;
}
/* Classical double-line rule separator */
.folio-double-rule {
  position: relative;
  height: 4px;
  border-top: 1px solid #c5c6ce;
  border-bottom: 0.5px solid #dfdad0;
}
/* Subtle parchment background tooth */
body {
  background-color: #fdf9f1;
  color: #1c1c17;
}

/* Handcrafted tactile paper tooth & ruling mechanics */
.folio-container {
  width: 400px;
  min-height: 600px;
  background-color: #fdf9f1;
  box-shadow: 0 4px 20px rgba(74, 59, 50, 0.12), 0 1px 3px rgba(74, 59, 50, 0.08);
  position: relative;
}

.double-rule {
  border-top: 1px solid #d8cfbe;
  border-bottom: 0.5px solid #d8cfbe;
  height: 3px;
}

.brass-clip-accent {
  background: linear-gradient(135deg, #c49a45 0%, #8f6b28 100%);
  box-shadow: 0 1px 2px rgba(0,0,0,0.25);
}

.material-symbols-outlined {
  font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 20;
  font-size: 18px;
  line-height: 1;
  display: inline-block;
  vertical-align: middle;
}
